/*
 * A170552  Number of reduced words of length n in Coxeter group on 15
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^47 = I.
 * https://oeis.org/A170552
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the linear recurrence derived from the
 *            rational generating function (t^47 + 2t^46 + … + 2t + 1)/(1 –
 *            13t – 13t² – … – 13t^46 + 91t^47) For n = 0, a(0) = 1. For n ≥ 1
 *            p = 1 if n = 0 or n = 47 p = 2 if 1 ≤ n ≤ 46 p = 0 otherwise sum
 *            = a[n-1] + a[n-2] + … + a[n-min(46,n)] a[n] =...
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 8, u64 n <= 16, u128 n <= 16,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>   /* for size_t */
#include <stdlib.h>   /* for malloc, free */

seq_t a(idx_t n) {
    /* Cache for memoization of computed terms */
    static seq_t *cache = NULL;   /* array of terms */
    static size_t cap   = 0;      /* current allocation size (in terms) */
    static size_t size  = 0;      /* number of terms currently stored */

    /* Ensure the cache is large enough for n+1 terms */
    if ((size_t)n + 1 > cap) {
        size_t new_cap = cap ? (cap << 1) : 64;      /* grow exponentially */
        while (new_cap <= (size_t)n) new_cap <<= 1;

        seq_t *new_cache = (seq_t*)malloc(new_cap * sizeof(seq_t));
        if (!new_cache) return 0;                      /* allocation failed */

        /* copy old data if any */
        if (cache) {
            for (size_t i = 0; i < size; ++i) new_cache[i] = cache[i];
            free(cache);
        }
        cache = new_cache;
        cap   = new_cap;
    }

    /* Compute terms up to n, if not already computed */
    for (idx_t i = size; i <= n; ++i) {
        /* Compute constant term p_i of the numerator */
        seq_t p = 0;
        if (i == 0 || i == 47)          p = 1;
        else if (i <= 46)               p = 2;
        /* p = 0 for i > 47 automatically */

        /* sum of the last up to 46 terms */
        seq_t sum = 0;
        idx_t k = (i < 46 ? i : 46);
        for (idx_t j = 1; j <= k; ++j)  sum += cache[i - j];

        seq_t val = p + (seq_t)13 * sum;
        if (i >= 47)
            val -= (seq_t)91 * cache[i - 47];

        cache[i] = val;
    }
    size = n + 1;
    return cache[n];
}
